<template>
    <!-- select -->
    <div class="newMonster">
        <p class="choose">
            <span>选择任务：</span>
            <a-select
                v-model:value="itemType"
                :options="monsterList"
                show-search
                @change="chooseMonster"
            ></a-select>
        </p>
        <p class="choose">
            <span>进攻次数：</span>
            <a-input v-model:value="times"></a-input>
        </p>
        <a-button type="primary" @click="toNewMonster">
            {{ $t("attack") }}
        </a-button>
    </div>
    <FightModal
        :fightLog="fightLog"
        :modalVisible="modalVisible"
        :spoils="spoils"
        @submit="modalClose"
    ></FightModal>
</template>
<script>
import { useI18n } from "vue-i18n";
import { createVNode, onMounted, reactive, toRefs } from "vue";
import FightModal from "@/components/fight/FightModal.vue";
import { Modal } from "ant-design-vue";
import fightApi from "@/assets/api/fightApi";

export default {
    name: "Monster", // 清缴小贼
    components: { FightModal },
    // 战斗
    setup(props, ctx) {
        const { t } = useI18n();
        const state = reactive({
            uid: sessionStorage.getItem("uid"),

            fightLog: [], // 战斗日志
            spoils: [], // 战利品
            modalVisible: false, // 战斗日志弹窗

            // 清剿小贼 任务列表
            monsterList: [
                {
                    label: t("gainWeapon"),
                    value: "2"
                },
                {
                    label: t("gainArmor"),
                    value: "3"
                },
                {
                    label: t("gainOrnament"),
                    value: "4"
                }
            ],
            // 选中的任务类型（即道具类型）
            itemType: "2",
            // 次数
            times: "1"
        });

        const toNewMonster = () => {
            //  二次确认
            Modal.confirm({
                title: `${t("attackMonsterTips")} ${state.times} 次${t("toMonster")}?`,
                content: createVNode("div", { style: "color:red;" }),
                async onOk() {
                    let res = await fightApi.toMonster({
                        uid: state.uid,
                        itemType: state.itemType,
                        monsterType: "monster",
                        times: state.times
                    });
                    state.fightLog = res.data.fightLog;
                    state.spoils = res.data.spoils;
                    state.modalVisible = true;

                    // 获取角色信息
                    ctx.emit("refresh", "这是子组件传递的数据");
                }
            });
        };

        const chooseMonster = (value, role) => {
            console.log(value, role);
        };

        // 关闭弹窗
        const modalClose = () => {
            state.modalVisible = false;
        };

        return {
            ...toRefs(state),
            chooseMonster,
            modalClose,
            toNewMonster
        };
    }
};
</script>

