<template>
    <a-modal
        v-model:open="modalVisible"
        :title="$t('battleLog')"
        width="1024px"
    >
        <!-- 战利品 -->
        <div class="spoilsBox">
            <span>战利品：</span>
            <span v-if="spoils.length === 0">无</span>
            <template v-else>
            <span v-for="item in spoils" style="margin-right: 5px">
                {{ item.name }}
            </span>
            </template>
        </div>
        <!-- 对战图 -->
        <div class="vsBox">
            <div v-for="(item, index) in fightLog"
                 class="vs"
                 :class="{'lose': item.length % 2 === 0, 'win': item.length % 2 !== 0}"
                 @click="chooseLog(item)">
                {{ index + 1 }} {{ item[0].nicknameB }}
            </div>
        </div>
        <p class="logTitle" v-if="fightLogRender[0]">对战 {{ fightLogRender[0].nicknameB }}</p>
        <div class="logBox">
            <div class="logs" v-for="(item, index) in fightLogRender">
                <p>{{ $t("round") }} {{ index + 1 }}</p>
                <div class="logsItem">
                    <div class="nicknameA">
                        <span>{{ item.nicknameA }}</span>
                        <span class="oriHp">
                            <span class="hp" :style="`width: ${item.aggressor.hpPercent}px`"></span>
                        </span>
                        <span>{{ item.aggressor.hpPercent }}%</span>
                        <span>hp: {{ item.aggressor.hp }}/{{ item.aggressor.oriHp }}</span>
                        <span>{{ $t("waigong") }}: {{ item.aggressor.waigong }}</span>
                        <span>{{ $t("neigong") }}: {{ item.aggressor.neigong }}</span>
                        <span>{{ $t("waifang") }}: {{ item.aggressor.waifang }}</span>
                        <span>{{ $t("neifang") }}: {{ item.aggressor.neifang }}</span>
                        <span>{{ $t("huixin") }}: {{ item.aggressor.huixin }}</span>
                        <span>{{ $t("huishang") }}: {{ item.aggressor.huishang }}</span>
                        <span>{{ $t("renxing") }}: {{ item.aggressor.renxing }}</span>
                    </div>
                    <div class="detail">
                        {{ item.aggressor.nickname }} 对
                        {{ item.victim.nickname }} 造成了 {{ item.damage }}点
                        {{ item.crit ? "暴击伤害" : "伤害" }}
                    </div>
                    <div class="nicknameB">
                        <span>{{ item.nicknameB }}</span>
                        <span class="oriHp">
                            <span class="hp" :style="`width: ${item.victim.hpPercent}px`"></span>
                        </span>
                        <span>{{ item.victim.hpPercent }}</span>
                        <span>hp: {{ item.victim.hp }}/{{ item.victim.oriHp }}</span>
                        <span>{{ $t("waigong") }}: {{ item.victim.waigong }}</span>
                        <span>{{ $t("neigong") }}: {{ item.victim.neigong }}</span>
                        <span>{{ $t("waifang") }}: {{ item.victim.waifang }}</span>
                        <span>{{ $t("neifang") }}: {{ item.victim.neifang }}</span>
                        <span>{{ $t("huixin") }}: {{ item.victim.huixin }}</span>
                        <span>{{ $t("huishang") }}: {{ item.victim.huishang }}</span>
                        <span>{{ $t("renxing") }}: {{ item.victim.renxing }}</span>
                    </div>
                </div>
            </div>
        </div>
        <template #footer>
            <a-button type="primary" @click="submit" @cancel="submit">
                关闭
            </a-button>
        </template>
    </a-modal>
</template>

<script>
import { computed, onMounted, reactive, toRefs, watch } from "vue";

export default {
    name: "FightModal",
    props: {
        modalVisible: {
            default: false,
            type: Boolean
        },
        fightLog: {
            default: [],
            type: Array
        },
        spoils: {
            default: [],
            type: Array
        }
    },
    emits: ["submit"],
    setup(props, ctx) {
        const state = reactive({
            showLog: [] // 显示的log
        });

        const chooseLog = (item) => {
            state.showLog = item;
        };

        // 计算 添加 血量百分比
        const fightLogRender = computed(() => {
            // 血量百分比
            let aggressorHpPercent = 0,
                victimHpPercent = 0;

            return state.showLog.map((i, index) => {
                // 攻击者
                // 奇数 主角 偶数 敌方
                let aggressor = {}, // 攻击者
                    victim = {}; // 被攻击者
                if (index % 2 === 0) {
                    aggressor = JSON.parse(JSON.stringify(i.attrA));
                    victim = JSON.parse(JSON.stringify(i.attrB));
                } else {
                    aggressor = JSON.parse(JSON.stringify(i.attrB));
                    victim = JSON.parse(JSON.stringify(i.attrA));
                }

                // 血量百分比
                aggressorHpPercent = (aggressor.hp / aggressor.oriHp) * 100;
                victimHpPercent = (victim.hp / victim.oriHp) * 100;

                let res = {
                    ...i,
                    aggressor: {
                        ...aggressor,
                        hpPercent:
                            aggressorHpPercent > 0
                                ? aggressorHpPercent.toFixed(2)
                                : "0"
                    },
                    victim: {
                        ...victim,
                        hpPercent:
                            victimHpPercent > 0
                                ? victimHpPercent.toFixed(2)
                                : "0"
                    }
                };
                return res;
            });
        });

        const submit = () => {
            ctx.emit("submit");
        };

        return {
            ...toRefs(props),
            ...toRefs(state),
            fightLogRender,
            submit,
            chooseLog
        };
    }
};
</script>

