    setup() {
        const { t } = useI18n();
        const state = reactive({
            uid: sessionStorage.getItem("uid"),
            missionPoint: "",
            enemyName: "",
            enemyId: "",

            roleOptionsList: [], // 人员列表

            fightLog: [], // 战斗日志
            spoils: [], // 战利品
            currentMonsterWinRate: "0%", // monster 胜率
            currentBossWinRate: "0%", // boss 胜率
            modalVisible: false, // 战斗日志弹窗

            // 进攻次数
            weaponTimes: 1,
            armorTimes: 1,
            ornamentTimes: 1,
            bossTimes: 1


