            // 获取所有角色列表
            await getRoleList();
            // await toImitMonster();
            // await toImitBoss();
        });

        // 获取所有角色列表
        const getRoleList = async () => {
            let res = await roleApi.getRoleList({});
            state.roleOptionsList = res.data
                .filter((i) => i.uid !== state.uid)
                .map((i) => {
                    return {
                        label: i.nickname,
                        value: i.uid
                    };
                });
            state.missionPoint = res.data.find(
                (i) => i.uid === state.uid
            ).missionpoint;
        };

        // 获取角色信息
        const getRoleInfo = async () => {
            let res = await roleApi.getInfo({
                uid: state.uid
            });
            state.missionPoint = res.data.roleInfo.missionpoint;
        };

        // attack to role
        const toRole = async () => {
            //  二次确认
            Modal.confirm({
                title: `${t("attackRoleTips")}：${state.enemyName}?`,
                content: createVNode("div", { style: "color:red;" }),
                okText: t("attack"),
                cancelText: t("cancel"),
                async onOk() {
                    let res = await fightApi.toRole({
                        uid: state.uid,
                        enemyId: String(state.enemyId)
                    });
                    state.fightLog = res.data.fightLog;
                    state.spoils = res.data.spoils;
                    state.modalVisible = true;

                    // 获取角色信息
                    await getRoleInfo();
                }
            });
        };

        const toMonster = async (itemType, monsterType, times) => {
            //  二次确认
            Modal.confirm({
                title: `${t("attackMonsterTips")}：${t("toMonster")}?`,
                content: createVNode("div", { style: "color:red;" }),
                async onOk() {
                    let res = await fightApi.toMonster({
                        uid: state.uid,
                        itemType: itemType,
                        monsterType: monsterType,
                        times: times
                    });
                    state.fightLog = res.data.fightLog;
                    state.spoils = res.data.spoils;
                    state.modalVisible = true;

                    // 获取角色信息
                    await getRoleInfo();
                }
            });
        };

